import React from 'react';
import DiscoverFeed from './DiscoverFeed';
import { useFeatureFlag } from '../context/FeatureFlagContext';

const DiscoverWrapper = (props) => {
  const { isEnabled } = useFeatureFlag();
  const { setActiveTab } = props;

  const isLocationEnabled = isEnabled('locationServices');
  const isPassportEnabled = isEnabled('passportMode');

  return (
    <div style={{ position: 'relative', width: '100%', height: '100%' }}>
      {/* EXISTING COMPONENT - RENDERED EXACTLY AS BEFORE */}
      <DiscoverFeed {...props} />

      {/* NEW FEATURES - OVERLAY ON TOP (Non-invasive) */}
      <div style={{
        position: 'absolute',
        top: '20px',
        right: '20px',
        display: 'flex',
        flexDirection: 'column',
        gap: '10px',
        zIndex: 100,
        pointerEvents: 'none' // Let clicks pass through if not on buttons
      }}>

        {isLocationEnabled && (
          <div style={{
            background: 'var(--color-primary, #FF6B6B)',
            color: 'white',
            padding: '8px 12px',
            borderRadius: '20px',
            boxShadow: '0 4px 6px rgba(0,0,0,0.1)',
            fontWeight: 'bold',
            fontSize: '12px',
            pointerEvents: 'auto',
            display: 'flex',
            alignItems: 'center',
            gap: '5px'
          }}>
            📍 Location Active
          </div>
        )}

        {isPassportEnabled && (
          <button 
            onClick={() => setActiveTab('passport')}
            style={{
              background: 'linear-gradient(135deg, #9F7AEA 0%, #6B46C1 100%)',
              color: 'white',
              border: 'none',
              padding: '10px 15px',
              borderRadius: '20px',
              boxShadow: '0 4px 6px rgba(0,0,0,0.2)',
              fontWeight: 'bold',
              cursor: 'pointer',
              pointerEvents: 'auto',
              display: 'flex',
              alignItems: 'center',
              gap: '5px'
            }}
          >
            🌍 Passport
          </button>
        )}
      </div>
    </div>
  );
};

export default DiscoverWrapper;
